using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGlobals(); // DO NOT MODIFY THIS LINE

// The headless server is not on Steam; fetch the latest stable release into this server's game files folder
// (the create task copies it into the new service from there).
var target = Path.Combine(ThisServer.Configuration.GameFilesPath, ThisGame.FileAndDirectoryConfig.AutoSetupFolderName);
var http = new HttpClient();
await InstallHeadless(http, await LatestHeadless(http), target);
// Shared body of the Factorio install/update scripts: the headless server from factorio.com (Linux only), a tar.xz
// whose files sit under factorio/; extracted with the host's tar, which handles xz.
async Task<string> LatestHeadless(HttpClient http)
{
    using (var doc = JsonDocument.Parse(await http.GetStringAsync("https://factorio.com/api/latest-releases")))
        return doc.RootElement.GetProperty("stable").GetProperty("headless").GetString();
}

bool Shell(string command, out string output)
{
    using (var process = Process.Start(new ProcessStartInfo("/bin/sh", new[] { "-c", command }) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        output = process.StandardOutput.ReadToEnd() + process.StandardError.ReadToEnd();
        process.WaitForExit();
        return process.ExitCode == 0;
    }
}

async Task InstallHeadless(HttpClient http, string version, string target)
{
    Directory.CreateDirectory(target);
    var archive = Path.Combine(target, "factorio-headless.tar.xz");
    using (var response = await http.GetAsync("https://www.factorio.com/get-download/" + version + "/headless/linux64", HttpCompletionOption.ResponseHeadersRead, ThisCancellationToken))
    {
        response.EnsureSuccessStatusCode();
        using (var file = File.Create(archive)) await response.Content.CopyToAsync(file, ThisCancellationToken);
    }
    if (!Shell("tar -xJf '" + archive + "' --strip-components=1 -C '" + target + "'", out var tarOutput))
        throw new Exception("Extracting Factorio " + version + " failed (is xz-utils installed?): " + tarOutput);
    File.Delete(archive);
    File.WriteAllText(Path.Combine(target, "factorio-version.txt"), version);
    ScriptConsole.WriteLine((object)("Installed Factorio " + version + "."));
}

