//refAssemblies: TCAdmin.Monitor.SDK.dll, System.Diagnostics.Process.dll, System.Net.Http.dll, System.Text.Json.dll
using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// --start-server needs an existing save. Create the map on the first start (or after the save name changed).
// The save name comes from the active command line, because a customer's custom or predefined command line keeps
// its own SaveName value; the SaveName variable is the fallback.
var root = Path.GetFullPath((string)ThisService.RootDirectory);
var saveName = "";
var saveMatch = System.Text.RegularExpressions.Regex.Match(Convert.ToString(ThisService.Commandline) ?? "", @"--start-server\s+saves/(\S+?)\.zip(\s|$)");
if (saveMatch.Success) saveName = saveMatch.Groups[1].Value;
else if (ThisService.Variables.ContainsKey("SaveName")) saveName = Convert.ToString(ThisService.Variables["SaveName"]);
if (string.IsNullOrWhiteSpace(saveName)) saveName = "world";
if (!System.Text.RegularExpressions.Regex.IsMatch(saveName, "^[A-Za-z0-9_-]{1,64}$"))
    throw new Exception("Invalid save name '" + saveName + "': use 1-64 letters, digits, '-' or '_'.");
var savesDir = Path.Combine(root, "saves");
var save = Path.Combine(savesDir, saveName + ".zip");
if (!File.Exists(save))
{
    ScriptConsole.WriteLine((object)("Creating a new map: saves/" + saveName + ".zip"));
    var credential = ServiceManagerService.GetServiceCredential(ThisService.ServiceId);
    if (!Directory.Exists(savesDir))
    {
        Directory.CreateDirectory(savesDir);
        Globals.OperatingSystem.SetDirectoryOwner(savesDir, credential.Domain, credential.UserName, false);
    }
    // The map is created by the service user and without a shell (the save name is customer input).
    var runuser = File.Exists("/usr/sbin/runuser") ? "/usr/sbin/runuser" : "/sbin/runuser";
    var startInfo = new ProcessStartInfo(runuser) { WorkingDirectory = root, RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false };
    foreach (var argument in new[] { "-u", (string)credential.UserName, "--", Path.Combine(root, "bin", "x64", "factorio"), "--create", "saves/" + saveName + ".zip" })
        startInfo.ArgumentList.Add(argument);
    string createOutput;
    int exitCode;
    using (var process = Process.Start(startInfo))
    {
        var stdout = process.StandardOutput.ReadToEndAsync();
        var stderr = process.StandardError.ReadToEndAsync();
        process.WaitForExit();
        createOutput = stdout.Result + stderr.Result;
        exitCode = process.ExitCode;
    }
    if (exitCode != 0 || !File.Exists(save))
        throw new Exception("Creating the map failed (exit " + exitCode + "): " + createOutput);
}
